@push('scripts')<script>let cards=[];function refreshCards(){cards=[...document.querySelectorAll('.post-card')].sort((a,b)=>((b.classList.contains('hard')?1:0)-(a.classList.contains('hard')?1:0)));cards.forEach(c=>c.parentElement.appendChild(c));applyFilter()}refreshCards();search=document.getElementById('postSearch');let activeSector='ALL',activeTags=[];function applyFilter(){const tokens=search.value.toLowerCase().split(/\s+/).filter(Boolean);const qTags=tokens.filter(t=>t.startsWith('#')).map(t=>t.slice(1)).filter(Boolean);const words=tokens.filter(t=>!t.startsWith('#'));cards.forEach(c=>{const tags=(c.dataset.tags||'').split(/\s+/).filter(Boolean);const show=(activeSector==='ALL'||c.dataset.sector===activeSector)&&qTags.every(t=>tags.includes(t))&&activeTags.every(t=>tags.includes(t))&&words.every(w=>(c.dataset.search||'').includes(w));c.classList.toggle('hidden',!show)})}search.addEventListener('input',applyFilter);document.querySelectorAll('.sector').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sector').forEach(x=>x.classList.remove('border-white','bg-pitch-800'));b.classList.add('border-white','bg-pitch-800');activeSector=b.dataset.sector;applyFilter()});document.querySelectorAll('.tag-chip').forEach(t=>t.onclick=()=>{if(activeTags.includes(t.dataset.tag)){activeTags=activeTags.filter(x=>x!==t.dataset.tag);t.classList.remove('border-white','text-white')}else{activeTags.push(t.dataset.tag);t.classList.add('border-white','text-white')}applyFilter()});const threadModal=document.getElementById('threadModal');function escHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}function ytId(u){const m=u.match(/(?:youtu\.be\/|v=|embed\/|shorts\/)([A-Za-z0-9_-]{11})/);return m?m[1]:null}function richText(s){const urls=[];let h=s.replace(/(https?:\/\/[^\s]+)/g,m=>{urls.push(m);return '\u0001'+(urls.length-1)+'\u0001'});h=escHtml(h);h=h.replace(/(^|\s)#([a-z0-9_\-]+)/gi,(m,pre,tag)=>pre+'<span class="hashtag text-white font-bold cursor-pointer" data-tag="'+tag.toLowerCase()+'">#'+tag+'</span>');h=h.replace(/\u0001(\d+)\u0001/g,(m,i)=>{const u=urls[+i];const y=ytId(u);if(y)return '<a href="'+u+'" target="_blank" rel="noopener"><img src="https://i.ytimg.com/vi/'+y+'/hqdefault.jpg" class="my-3 w-full max-w-md border border-silver-700" alt="video preview"></a>';return '<a href="'+u+'" target="_blank" rel="noopener" class="break-all text-white underline">'+u+'</a>'});return h}function runFilterTag(tag){search.value='#'+tag;applyFilter()}document.addEventListener('click',e=>{const b=e.target.closest('.read-post');if(!b)return;modalTitle.textContent=b.dataset.title;window.txPhotos=(b.dataset.media||'').split(',').filter(Boolean).map(p=>'/posts/'+p.split('/').pop());window.txPhotoIdx=0;window.txRenderPhoto=()=>{if(!modalMedia)return;if(!window.txPhotos.length){modalMedia.innerHTML='';return}modalMedia.innerHTML='<div class="relative">'+'<img src="'+window.txPhotos[window.txPhotoIdx]+'" class="w-full border border-silver-700 max-h-[70vh] object-contain" alt="attached media">'+(window.txPhotos.length>1?'<button type="button" id="txPrev" class="absolute left-2 top-1/2 -translate-y-1/2 border border-silver-600 bg-pitch-950/90 px-3 py-2 text-white hover:border-white">&#9664;</button>'+'<button type="button" id="txNext" class="absolute right-2 top-1/2 -translate-y-1/2 border border-silver-600 bg-pitch-950/90 px-3 py-2 text-white hover:border-white">&#9654;</button>'+'<span class="absolute bottom-2 right-2 border border-silver-600 bg-pitch-950/90 px-2 py-1 text-[10px] text-silver-300">'+(window.txPhotoIdx+1)+' / '+window.txPhotos.length+'</span>':'')+'</div>';const pv=document.getElementById('txPrev'),nx=document.getElementById('txNext');if(pv)pv.onclick=()=>{window.txPhotoIdx=(window.txPhotoIdx-1+window.txPhotos.length)%window.txPhotos.length;window.txRenderPhoto()};if(nx)nx.onclick=()=>{window.txPhotoIdx=(window.txPhotoIdx+1)%window.txPhotos.length;window.txRenderPhoto()}};window.txRenderPhoto();modalBody.innerHTML=richText(b.dataset.body);threadModal.classList.remove('hidden');threadModal.classList.add('flex');const pidCard=b.closest('.post-card');loadComments(pidCard?pidCard.dataset.postId:null)});document.addEventListener('click',e=>{const h=e.target.closest('.hashtag');if(h)runFilterTag(h.dataset.tag)});const modalCommentsList=document.getElementById('modalCommentsList');let currentPost=null;function timeShort(s){return s.replace(/^(\d+)\s+(\w+).*$/,'$1$2 ago')}function commentNode(c,depth){const rep=(c.replies||[]).map(r=>commentNode(r,depth+1)).join('');const mine=c.mine||'';return '<div class="comment-node mb-3 '+(depth?'border-l-2 border-silver-800 pl-3':'border border-silver-800 bg-pitch-900 p-3')+'" '+(depth?'style="margin-left:4px"':'')+'><p class="text-[10px] text-silver-500">BY <strong class="text-white">'+escHtml(String(c.author||'').toUpperCase())+'</strong> &middot; '+escHtml(c.time||'')+'</p><p class="mt-1 whitespace-pre-line text-xs leading-6 text-silver-300">'+richText(c.body||'')+'</p><div class="mt-2 flex flex-wrap items-center gap-2 text-[10px] text-silver-500"><button class="creact-btn border border-silver-700 px-2 py-1 hover:border-white hover:text-white" data-cid="'+c.id+'" data-react="up" '+(mine==='up'?'style="color:#fff;border-color:#fff"':'')+'>&#9650; <span class="creact-count">'+(c.up||0)+'</span></button><button class="creact-btn border border-silver-700 px-2 py-1 hover:border-white hover:text-white" data-cid="'+c.id+'" data-react="down" '+(mine==='down'?'style="color:#fff;border-color:#fff"':'')+'>&#9660; <span class="creact-count">'+(c.down||0)+'</span></button><button class="creply-btn border border-silver-700 px-2 py-1 hover:border-white hover:text-white" data-cid="'+c.id+'">REPLY</button></div><div class="creply-box hidden mt-2" id="creply-'+c.id+'"></div>'+(rep?'<div class="mt-3 space-y-3">'+rep+'</div>':'')+'</div>'}function commentForm(pid,parentId){return '<form class="cform grid gap-2" data-pid="'+pid+'" data-parent="'+(parentId||'')+'"><textarea name="body" required rows="2" class="border border-silver-700 bg-pitch-950 p-2 text-xs outline-none focus:border-white" placeholder="'+(parentId?'Write a reply...':'Add a reply to this transmission...')+'"></textarea><button class="justify-self-start bg-white px-3 py-1 text-[10px] font-bold tracking-widest text-black">'+(parentId?'SEND REPLY':'TRANSMIT REPLY')+'</button></form>'}async function loadComments(pid){const res=await fetch('/community/posts/'+pid+'/comments',{headers:{'Accept':'application/json'}});if(!res.ok){modalCommentsList.innerHTML='<p class="text-xs text-silver-500">Replies unavailable right now.</p>';return}const d=await res.json();if(!d.ok){modalCommentsList.innerHTML='<p class="text-xs text-silver-500">Replies unavailable right now.</p>';return}currentPost=pid;const list=(d.comments||[]).map(c=>commentNode(c,0)).join('');modalCommentsList.innerHTML=(list||'<p class="text-xs text-silver-500">No replies yet. Be the first signal.</p>')+commentForm(pid,null)}modalCommentsList.addEventListener('click',async e=>{const r=e.target.closest('.creact-btn');if(r){const v=r.dataset.react;const csrf=document.querySelector('meta[name=csrf-token]')?.content;const res=await fetch('/community/comments/'+r.dataset.cid+'/react',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({value:v})});if(!res.ok)return;const d=await res.json();if(!d.ok)return;const node=r.closest('.comment-node');node.querySelectorAll('.creact-btn').forEach(btn=>{const cnt=btn.querySelector('.creact-count');cnt.textContent=(btn.dataset.react==='up')?d.up:d.down;btn.style.color=(d.mine===btn.dataset.react)?'#fff':'';btn.style.borderColor=(d.mine===btn.dataset.react)?'#fff':''});return}const rp=e.target.closest('.creply-btn');if(rp){const box=document.getElementById('creply-'+rp.dataset.cid);if(!box)return;if(box.classList.contains('hidden')){box.innerHTML=commentForm(currentPost,rp.dataset.cid);box.classList.remove('hidden');rp.textContent='CANCEL';const ta=box.querySelector('textarea');if(ta)ta.focus()}else{box.classList.add('hidden');rp.textContent='REPLY'}}});modalCommentsList.addEventListener('submit',async e=>{const f=e.target.closest('.cform');if(!f)return;e.preventDefault();const body=f.querySelector('textarea[name=body]').value.trim();if(!body)return;const csrf=document.querySelector('meta[name=csrf-token]')?.content;const payload={body};if(f.dataset.parent)payload.parent_id=parseInt(f.dataset.parent,10);const res=await fetch('/community/posts/'+f.dataset.pid+'/comments',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(payload)});if(!res.ok){alert('Reply could not be transmitted right now.');return}loadComments(f.dataset.pid)});document.addEventListener('click',async e=>{const b=e.target.closest('.react-btn');if(!b)return;e.preventDefault();const card=b.closest('.post-card');const pid=card?card.dataset.postId:null;if(!pid)return;const v=b.dataset.react;const csrf=document.querySelector('meta[name=csrf-token]')?.content;const res=await fetch('/community/posts/'+pid+'/react',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({value:v})});if(!res.ok)return;const d=await res.json();if(!d.ok)return;card.querySelectorAll('.react-btn').forEach(btn=>{const cnt=btn.querySelector('.react-count');cnt.textContent=(btn.dataset.react==='up')?d.up:d.down;btn.style.color=(d.mine===btn.dataset.react)?'#fff':'';btn.style.borderColor=(d.mine===btn.dataset.react)?'#fff':''})})</script>@endpush

