<style>#tx-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.75);z-index:50;overflow:auto;padding:2rem 1rem}#tx-overlay.open{display:block}#tx-card{max-width:42rem;margin:0 auto;background:#0a0a0c;border:1px solid #3f3f46;padding:1.5rem}</style>
<script>function openTransmission(){const sec=document.getElementById('new-transmission');if(!sec)return;let ov=document.getElementById('tx-overlay');if(!ov){ov=document.createElement('div');ov.id='tx-overlay';const card=document.createElement('div');card.id='tx-card';const close=document.createElement('button');close.type='button';close.textContent='× CLOSE';close.className='mb-4 block w-full border border-red-600 p-2 text-xs font-bold tracking-widest text-red-500';close.onclick=closeTransmission;ov.appendChild(close);ov.appendChild(card);document.body.appendChild(ov);card.appendChild(sec);sec.style.display='block'}ov.classList.add('open');document.body.style.overflow='hidden'}function closeTransmission(){const ov=document.getElementById('tx-overlay');if(ov)ov.classList.remove('open');document.body.style.overflow=''}const txBox=document.querySelector('#new-transmission textarea[name=body]');function txAutoSize(){if(!txBox)return;txBox.style.height='auto';txBox.style.height=Math.min(txBox.scrollHeight+2,600)+'px'}if(txBox){txBox.addEventListener('input',txAutoSize);txBox.addEventListener('keydown',e=>{if(e.key==='Enter')txAutoSize()})}</script>
