<script>
function loadNewTx(){const pill=document.getElementById('newTxNotif');if(pill)pill.textContent='LOADING NEW TRANSMISSIONS...';fetch('/community/fresh?since='+encodeURIComponent(pill?pill.dataset.since:''),{headers:{'Accept':'text/html','X-Requested-With':'fetch'}}).then(r=>{if(!r.ok)throw 0;return r.text().then(h=>({h,n:r.headers.get('X-New-Count')||'0'}))}).then(({h,n})=>{const grid=document.getElementById('postGrid');const tmp=document.createElement('div');tmp.innerHTML=h;const anchor=document.getElementById('pinnedDirective');let added=0;[...tmp.querySelectorAll('.post-card')].forEach(c=>{const pid=c.dataset.postId;if(grid.querySelector('.post-card[data-post-id="'+pid+'"]')){c.remove();return}added++;(anchor&&anchor.parentElement===grid?anchor:grid).insertAdjacentElement('afterend',c)});if(pill)pill.remove();refreshCards();if(!added)grid.scrollIntoView({behavior:'smooth'})}).catch(()=>{if(pill)pill.textContent='COULD NOT LOAD - TAP TO RETRY'})}
function bindLoadMore(link) {
  if (!link || link.dataset.bound) return;
  link.dataset.bound = '1';
  link.addEventListener('click', async event => {
    event.preventDefault();
    const m0 = (link.getAttribute('href') || '').match(/posts_page=(\d+)/);
    const page = m0 ? m0[1] : '2';
    const url = '/community/more?posts_page=' + page;
    link.textContent = 'LOADING TRANSMISSIONS...';
    try {
      const r = await fetch(url, {headers: {'X-Requested-With': 'fetch', 'Accept': 'text/html'}});
      if (!r.ok) { window.location = url; return; }
      const html = await r.text();
      const hasMore = r.headers.get('X-Has-More') === '1';
      const grid = document.getElementById('postGrid');
      link.remove();
      grid.insertAdjacentHTML('beforeend', html);
      refreshCards();
      if (hasMore) {
        const m = url.match(/posts_page=(\d+)/);
        const next = m ? (parseInt(m[1], 10) + 1) : 3;
        const a = document.createElement('a');
        a.href = url.split('?')[0] + '?posts_page=' + next;
        a.className = 'block border border-silver-700 bg-pitch-900 p-3 text-center text-xs tracking-widest text-silver-300 hover:border-white hover:text-white';
        a.textContent = 'LOAD MORE TRANSMISSIONS';
        grid.appendChild(a);
        bindLoadMore(a);
      }
    } catch (e) { window.location = url; }
  });
}
document.querySelectorAll('#postGrid a[href*="posts_page="]').forEach(bindLoadMore);
const qp=new URLSearchParams(location.search).get('open_post');if(qp){const ob=document.querySelector('.post-card[data-post-id="'+qp+'"] .read-post');if(ob){ob.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>ob.click(),250)}}
</script>
